fn any_int(x: i8, y: i8, z: i8) -> bool {
    // Promote to a larger signed type to avoid overflow in the sums
    let x16 = x as i16;
    let y16 = y as i16;
    let z16 = z as i16;

    // Check if any one is exactly the sum of the other two
    x16 == y16 + z16
        || y16 == x16 + z16
        || z16 == x16 + y16
}

